<div x-data="employeeList({{ Illuminate\Support\Js::from($employees) }})" class="space-y-5">
 <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-semibold text-gray-900">Employee directory</h2><p class="text-sm text-gray-600">Browse and manage your workforce.</p></div><button @click="addOpen=true" class="rounded-lg bg-[#0b1f33] px-4 py-2.5 text-sm font-semibold text-white">Add Employee</button></div>
 <div class="grid gap-3 sm:grid-cols-3"><input x-model.debounce.300ms="search" aria-label="Search employees" placeholder="Search name or employee ID" class="rounded-lg border p-2.5"><select x-model="status" class="rounded-lg border p-2.5" aria-label="Filter employment status"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select><select x-model="department" class="rounded-lg border p-2.5" aria-label="Filter department"><option value="">All departments</option><template x-for="d in departments" :key="d"><option x-text="d"></option></template></select></div>
 <div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50 text-gray-700"><tr><th class="p-3">Employee ID</th><th class="p-3">Full Name</th><th class="p-3">Position</th><th class="p-3">Department</th><th class="p-3">Employment Type</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><template x-for="e in pageRows" :key="e.employee_id"><tr class="border-t"><td class="p-3" x-text="e.employee_id"></td><td class="p-3 font-medium"><a class="text-teal-800 underline" :href="'/employees/'+e.employee_id" x-text="e.full_name"></a></td><td class="p-3" x-text="e.position"></td><td class="p-3" x-text="e.department"></td><td class="p-3" x-text="e.employment_type"></td><td class="p-3"><span class="rounded-full bg-green-100 px-2.5 py-1 text-sm text-green-900" x-text="e.employment_status"></span></td><td class="p-3"><button @click="archive=e;archiveOpen=true" class="text-red-700 underline">Archive</button></td></tr></template><tr x-show="!filtered.length"><td colspan="7" class="p-8 text-center text-gray-700" x-text="`No employees found${search ? ' for “'+search+'”' : ''}.`"></td></tr></tbody></table></div>
 <div class="flex items-center justify-between text-sm" x-show="filtered.length>10"><span x-text="`Page ${page} of ${pages}`"></span><div class="flex gap-2"><button @click="page=Math.max(1,page-1)" :disabled="page===1" class="rounded border px-3 py-2 disabled:opacity-40">Previous</button><button @click="page=Math.min(pages,page+1)" :disabled="page===pages" class="rounded border px-3 py-2 disabled:opacity-40">Next</button></div></div>
 <div x-show="addOpen" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4" @click.self="addOpen=false"><form @submit.prevent="submit" class="w-full max-w-2xl space-y-4 rounded-xl bg-white p-6" x-trap.inert.noscroll="addOpen||archiveOpen" role="dialog" aria-modal="true"><div class="flex justify-between"><h3 class="text-lg font-semibold">Add Employee</h3><button type="button" @click="addOpen=false" aria-label="Close dialog">✕</button></div><div class="grid gap-3 sm:grid-cols-2"><template x-for="f in fields" :key="f"><label class="text-sm font-medium" x-text="f.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())"><input :name="f" x-model="form[f]" required class="mt-1 block w-full rounded-lg border p-2.5"><span class="text-sm text-red-700" x-show="errors[f]" x-text="errors[f]"></span></label></template><label class="text-sm font-medium">Department<input x-model="form.department" required class="mt-1 block w-full rounded-lg border p-2.5"></label><label class="text-sm font-medium">Pay Rate<input type="number" min=".01" step=".01" x-model="form.pay_rate" required class="mt-1 block w-full rounded-lg border p-2.5"></label></div><div class="flex justify-end gap-2"><button type="button" @click="reset()" class="rounded-lg border px-4 py-2">Cancel</button><button class="rounded-lg bg-[#0b1f33] px-4 py-2 text-white">Save Employee</button></div></form></div>
 <div x-show="archiveOpen" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div class="w-full max-w-md rounded-xl bg-white p-6" x-trap.inert.noscroll="addOpen||archiveOpen" role="dialog" aria-modal="true"><h3 class="text-lg font-semibold">Archive employee?</h3><p class="my-3 text-sm">Archive <span x-text="archive?.full_name"></span> from this sample list?</p><div class="flex justify-end gap-2"><button @click="archiveOpen=false" class="rounded border px-4 py-2">Cancel</button><button @click="archive.employment_status='Inactive';archiveOpen=false;$dispatch('show-toast',{message:'Employee archived (demo).'})" class="rounded bg-red-700 px-4 py-2 text-white">Confirm</button></div></div></div>
</div>
<script>function employeeList(data){return {rows:data,search:'',status:'',department:'',page:1,addOpen:new URLSearchParams(location.search).get('modal')==='add',archiveOpen:false,archive:null,fields:['full_name','employee_id','position','employment_type'],form:{},errors:{},get departments(){return [...new Set(this.rows.map(e=>e.department))]},get filtered(){let q=this.search.toLowerCase();return this.rows.filter(e=>(!q||e.full_name.toLowerCase().includes(q)||e.employee_id.toLowerCase().includes(q))&&(!this.status||e.employment_status===this.status)&&(!this.department||e.department===this.department))},get pages(){return Math.max(1,Math.ceil(this.filtered.length/10))},get pageRows(){return this.filtered.slice((this.page-1)*10,this.page*10)},submit(){this.errors={};for(let f of [...this.fields,'department','pay_rate'])if(!this.form[f])this.errors[f]='This field is required.';if(Object.keys(this.errors).length)return;this.rows.unshift({...this.form,employment_status:'Active'});this.reset();this.$dispatch('show-toast',{message:'Employee added (demo).'})},reset(){this.form={};this.errors={};this.addOpen=false}}}</script>
@endsection
